(function () {
  'use strict';

  const ui = { query: '', filter: 'all', sort: 'newest', view: 'Front', reference: '', zoom: false, preview: false, request: false, followFilter: 'all' };
  const style = `<style>
  .cl-notice{display:flex;gap:12px;align-items:flex-start;background:#eef2ec;border-left:3px solid #72846c;padding:16px 20px;margin-bottom:24px;color:#43564a;font-size:14px;line-height:1.55}.cl-notice svg{flex-shrink:0;margin-top:2px}.cl-notice strong{color:#244b3d}.cl-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:24px 0}.cl-summary article{border-top:1px solid #cad4ca;padding:18px 0}.cl-summary strong{font-size:31px;font-weight:500;display:block;line-height:1.2;color:#244b3d}.cl-summary span{display:block;font-size:14px;color:#59665e;margin-top:5px}.cl-toolbar{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap;padding:20px;border-bottom:1px solid #dce2dc}.cl-toolbar .field{margin:0;min-width:150px}.cl-toolbar .cl-search{flex:1;min-width:200px}.cl-toolbar input,.cl-toolbar select,.cl-field input,.cl-field textarea,.cl-field select{width:100%;min-height:44px;padding:10px 12px;border:1px solid #cdd5cd;border-radius:4px;background:#fff;color:#202925;font:inherit}.cl-toolbar label,.cl-field label{display:block;font-size:13px;font-weight:600;margin-bottom:7px}.cl-table{width:100%;border-collapse:collapse;font-size:14px}.cl-table th{text-align:left;font-weight:600;color:#59665e;background:#f8f9f6;padding:13px 20px;white-space:nowrap}.cl-table td{padding:20px;vertical-align:middle;border-top:1px solid #e6eae3;line-height:1.45}.cl-table .cl-title{display:block;font-weight:600;color:#202925}.cl-table .cl-sub{display:block;color:#68756c;font-size:12px;margin-top:4px}.cl-table .cl-concern{max-width:250px}.cl-table .btn{white-space:nowrap}.cl-empty{padding:56px 24px;text-align:center;max-width:520px;margin:auto}.cl-empty h3{margin:16px 0 8px}.cl-empty p{color:#59665e;font-size:15px;line-height:1.6}.cl-bottomline{padding:15px 20px;border-top:1px solid #dce2dc;display:flex;justify-content:space-between;gap:12px;color:#68756c;font-size:12px}.cl-split{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(340px,.8fr);gap:24px;align-items:start}.cl-evidence{display:grid;grid-template-columns:1fr 1fr;gap:16px}.cl-photo{overflow:hidden;border:1px solid #dce2dc;border-radius:5px;background:#f0f2ee;min-height:210px;position:relative}.cl-photo>img,.cl-photo picture img{display:block;width:100%;height:100%;max-height:360px;object-fit:contain}.cl-photo>svg{width:100%;height:260px}.cl-photo .photo-placeholder{min-height:250px}.cl-photo.cl-zoom img{transform:scale(1.4)}.cl-photo-label{display:flex;justify-content:space-between;gap:6px;margin:10px 0 14px;font-size:12px;color:#59665e}.cl-photo-label strong{font-weight:600;color:#202925}.cl-evidence-tools{display:flex;flex-wrap:wrap;justify-content:space-between;gap:12px;margin-bottom:18px}.cl-evidence-tools select{border:1px solid #cdd5cd;background:white;min-height:38px;padding:8px;font:inherit;border-radius:4px;max-width:100%}.cl-tabs{display:flex;gap:4px;flex-wrap:wrap}.cl-tabs button{background:transparent;border:1px solid #dce2dc;border-radius:4px;padding:8px 12px;color:#59665e;font:inherit;font-size:13px;cursor:pointer}.cl-tabs button[aria-pressed=true]{background:#e8efe9;border-color:#a9b9a8;color:#244b3d}.cl-meta{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:20px 0 0}.cl-meta dt{font-size:12px;color:#68756c;margin-bottom:4px}.cl-meta dd{margin:0;font-size:14px;line-height:1.5}.cl-readout{padding:18px 0;border-bottom:1px solid #e1e6df}.cl-readout:first-child{padding-top:0}.cl-readout:last-child{border-bottom:0;padding-bottom:0}.cl-readout h4{font-size:13px;margin:0 0 7px;color:#59665e;font-weight:600}.cl-readout p{font-size:14px;line-height:1.65;margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.cl-source{display:inline-block;font-size:10px;letter-spacing:.07em;text-transform:uppercase;color:#6c796f;margin-bottom:8px}.cl-field{margin:0 0 18px}.cl-field textarea{min-height:95px;resize:vertical;line-height:1.55}.cl-field small{display:block;font-size:12px;color:#68756c;margin-top:5px;line-height:1.5}.cl-options{display:flex;flex-wrap:wrap;gap:8px}.cl-options label{border:1px solid #dce2dc;padding:10px;border-radius:4px;display:flex;align-items:center;gap:7px;font-size:13px;cursor:pointer}.cl-options input{min-height:auto;width:auto}.cl-options label:has(input:checked){border-color:#7f9787;background:#e8efe9}.cl-form-actions{display:flex;gap:10px;flex-wrap:wrap;border-top:1px solid #dce2dc;padding-top:20px}.cl-preview{border:1px solid #9eb19e;border-left:4px solid #244b3d;border-radius:5px;margin-top:22px;padding:22px;background:#fafcf8}.cl-preview h3{margin-top:0}.cl-history{display:flex;gap:10px;overflow-x:auto;padding:2px 0 8px}.cl-history a{display:block;min-width:145px;border:1px solid #dce2dc;padding:12px;color:#202925;text-decoration:none;border-radius:4px;font-size:13px}.cl-history a[aria-current=page]{background:#e8efe9;border-color:#9fb29f}.cl-history strong,.cl-history small{display:block}.cl-history small{margin-top:6px;color:#68756c}.cl-request{margin-top:20px;border-top:1px solid #dce2dc;padding-top:20px}.cl-follow{display:grid;grid-template-columns:95px minmax(0,1fr) auto;gap:24px;align-items:center;padding:24px 0;border-bottom:1px solid #dce2dc}.cl-follow:last-child{border-bottom:0}.cl-follow-date{border-left:3px solid #b2c0ac;padding-left:15px;font-size:14px;color:#59665e}.cl-follow-date b{display:block;color:#244b3d;font-size:26px;font-weight:500}.cl-follow h3{font-size:17px;margin:0 0 6px}.cl-follow p{font-size:14px;margin:6px 0;color:#59665e;line-height:1.5}.cl-service{display:flex;gap:16px;justify-content:space-between;padding:20px 0;border-bottom:1px solid #e0e6de;align-items:center}.cl-service:last-child{border-bottom:0}.cl-service h3{margin:0 0 5px;font-size:16px}.cl-service p{font-size:14px;line-height:1.5;color:#59665e;margin:0;max-width:560px}.cl-operational-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.cl-admin-nav{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:24px}.cl-admin-nav button{background:white;border:1px solid #dce2dc;border-radius:6px;text-align:left;padding:24px;color:#202925;cursor:pointer}.cl-admin-nav button:hover{border-color:#8ba18e;background:#fafbf8}.cl-admin-nav strong{display:block;font-size:17px;margin:16px 0 8px}.cl-admin-nav span{display:block;font-size:14px;line-height:1.6;color:#59665e}.cl-admin-nav .cl-link{margin-top:20px;color:#244b3d;font-weight:600}.cl-audit-event{padding:17px 0;border-bottom:1px solid #e1e6df;display:grid;grid-template-columns:145px 1fr;gap:20px;font-size:14px;line-height:1.5}.cl-audit-event:last-child{border-bottom:0}.cl-audit-event time{font-size:12px;color:#68756c}.cl-note-list{list-style:none;padding:0;margin:0}.cl-note-list li{padding:14px 0;border-bottom:1px solid #e0e5dc;font-size:14px;line-height:1.6}.cl-note-list li:last-child{border:0}.cl-note-list strong{display:block;margin-bottom:3px}.cl-person{width:38px;height:38px;background:#e8efe9;border:1px solid #cbd8c9;display:flex;align-items:center;justify-content:center;border-radius:5px;color:#244b3d;flex-shrink:0}.cl-person-row{display:flex;gap:13px;align-items:center}.cl-required{color:#765426}.cl-inert-note{font-size:12px;color:#68756c;line-height:1.5}.cl-heading-actions{display:flex;gap:12px;flex-wrap:wrap}.cl-hidden{display:none!important}.cl-btn-link{border:0;background:none;color:#244b3d;padding:0;font:inherit;font-size:13px;text-decoration:underline;text-underline-offset:3px;cursor:pointer}.cl-preview .btn{margin-top:16px}.cl-view-label{font-size:12px;color:#68756c;display:flex;gap:8px;align-items:center}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,a:focus-visible{outline:3px solid #9ab4a0;outline-offset:3px}
  @media(max-width:1100px){.cl-split{grid-template-columns:1fr}.cl-admin-nav{gap:12px}.cl-table td,.cl-table th{padding:15px}.cl-operational-grid{grid-template-columns:1fr}}@media(max-width:680px){.cl-summary{gap:14px}.cl-summary strong{font-size:27px}.cl-summary span{font-size:12px}.cl-notice{padding:14px}.cl-admin-nav{grid-template-columns:1fr}.cl-admin-nav button{padding:20px}.cl-admin-nav strong{margin:10px 0 6px}.cl-admin-nav .cl-link{margin-top:12px}.cl-toolbar{padding:16px;gap:10px}.cl-toolbar .field{flex:1;min-width:130px}.cl-evidence{gap:10px}.cl-photo{min-height:150px}.cl-photo>svg{height:170px}.cl-photo .photo-placeholder{min-height:160px}.cl-follow{grid-template-columns:65px 1fr;gap:14px;padding:20px 0}.cl-follow>.btn{grid-column:2;justify-self:start}.cl-follow-date{padding-left:10px}.cl-audit-event{grid-template-columns:1fr;gap:6px}.cl-service{align-items:flex-start;flex-wrap:wrap}.cl-meta{gap:14px}.cl-table{min-width:770px}.cl-bottomline{flex-direction:column}.cl-form-actions .btn{flex:1}.cl-heading-actions .btn{flex:1}.cl-preview{padding:17px}}
  .cl-split .notice,.cl-operational-grid .notice{display:block}.cl-split .notice p,.cl-operational-grid .notice p{margin-top:5px}.cl-photo .illustration-label{position:absolute;bottom:8px;left:8px;font-size:10px;background:#ffffffd9;padding:3px 5px;color:#64765d}
  </style>`;

  const esc = (PC, v) => PC.esc(String(v == null ? '' : v));
  const text = (v, fallback) => String(v == null || v === '' ? fallback || 'Not provided' : v);
  const sorted = arr => [...arr].sort((a, b) => new Date(b.date) - new Date(a.date));
  const sessions = PC => sorted((PC.state.sessions || []).filter(s => s.status !== 'Draft'));
  const shared = PC => PC.state.profile.assigned && PC.state.consents.sharing ? sessions(PC).filter(s => s.shared) : [];
  const accessible = (PC, id) => shared(PC).find(s => String(s.id) === String(id));
  const pending = s => !!s.guidanceNeedsReview || (!s.guidance && s.status !== 'Guidance published');
  const concern = s => text(s.answers && s.answers.concern, s.notes || 'No concern reported');
  const name = PC => esc(PC, PC.state.profile.name || 'Your progress record');
  const doctor = PC => esc(PC, PC.state.profile.doctor || 'Dr. Morgan Lee');
  const recordLabel = (PC, s) => `${esc(PC, s.title || (s.isBaseline ? 'Baseline session' : 'Weekly check-in'))}${s.sample ? ' <span class="cl-sub">Demonstration record</span>' : ' <span class="cl-sub">Saved upload</span>'}`;
  const audit = (PC, event) => { (PC.state.audit || (PC.state.audit = [])).push({ date: new Date().toISOString(), event }); };
  const save = async PC => { try { const result = await PC.save(); if (result === false) throw new Error('Save not completed'); return true; } catch (error) { PC.toast('The change could not be saved. Please try again.'); return false; } };
  const commit = async (PC, event, message) => { audit(PC, event); if (!await save(PC)) return false; PC.render(); if (message) PC.toast(message); return true; };
  const empty = (PC, title, desc, action) => `<div class="cl-empty">${PC.icon('clipboard', 30)}<h3>${title}</h3><p>${desc}</p>${action || ''}</div>`;
  const intro = PC => `<div class="cl-notice">${PC.icon('info', 18)}<div><strong>Doctor workspace demonstration.</strong> ${doctor(PC)} is a sample clinician. These reviews demonstrate the complete workflow and do not come from a medical professional.</div></div>`;
  const adminIntro = PC => `<div class="cl-notice">${PC.icon('shield', 18)}<div><strong>Administration preview.</strong> These controls demonstrate assignments and service operations. No verified clinician or live clinical review service is connected.</div></div>`;
  const heading = (eyebrow, title, desc, action) => `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="muted">${desc}</p></div>${action ? `<div class="cl-heading-actions">${action}</div>` : ''}</div>`;
  const panel = (title, subtitle, body, extra) => `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle ? `<p class="muted small">${subtitle}</p>` : ''}</div>${extra || ''}</div><div class="panel-body">${body}</div></section>`;
  const go = (route, label, classes) => `<button class="btn ${classes || ''}" data-go="${route}">${label}</button>`;

  function filteredQueue(PC) {
    let list = shared(PC);
    if (ui.filter === 'pending') list = list.filter(pending);
    if (ui.filter === 'published') list = list.filter(s => !!s.guidance);
    if (ui.filter === 'information') list = list.filter(s => s.status === 'More information needed' || s.status === 'Retake required');
    if (ui.query) { const q = ui.query.toLowerCase(); list = list.filter(s => `${PC.state.profile.name} ${s.title} ${s.id} ${concern(s)} ${s.status}`.toLowerCase().includes(q)); }
    if (ui.sort === 'oldest') list.reverse();
    if (ui.sort === 'concerns') list.sort((a, b) => Number(!!b.answers?.concern) - Number(!!a.answers?.concern));
    return list;
  }

  function queueRows(PC) {
    return filteredQueue(PC).map(s => `<tr><td><span class="cl-title">${name(PC)}</span><span class="cl-sub">${esc(PC, s.id)}</span></td><td><span class="cl-title">${PC.date(s.date)}</span><span class="cl-sub">${esc(PC, s.title || (s.isBaseline ? 'Baseline' : 'Weekly check-in'))}</span></td><td class="cl-concern">${esc(PC, concern(s))}</td><td>${PC.badge(s.status)}${s.sample ? '<span class="cl-sub">Demonstration</span>' : ''}</td><td><span>${s.guidance?.followUp ? PC.date(s.guidance.followUp) : 'Not scheduled'}</span><span class="cl-sub">${doctor(PC)} · Demo</span></td><td>${go('/doctor/review/' + encodeURIComponent(s.id), s.guidance ? 'View review' : 'Open review', 'small')}</td></tr>`).join('');
  }

  function queue(PC) {
    const list = shared(PC);
    const openRequests = list.filter(s => s.status === 'More information needed' || s.status === 'Retake required').length;
    return heading('REVIEW WORKSPACE', 'A clear view of every check-in.', 'Review shared photographs, read the customer’s update and write the next step.', go('/follow-ups', 'View follow-ups')) + intro(PC) +
      `<div class="cl-summary"><article><strong>${list.filter(pending).length.toString().padStart(2, '0')}</strong><span>Reviews to complete</span></article><article><strong>${openRequests.toString().padStart(2, '0')}</strong><span>Information requests</span></article><article><strong>${list.filter(s => !!s.guidance).length.toString().padStart(2, '0')}</strong><span>Demo guidance published</span></article></div>
      <section class="panel"><div class="panel-head"><div><h2>Assigned review queue</h2><p class="muted small">Only records shared with the assigned sample clinician appear here.</p></div><span class="tag">${doctor(PC)}</span></div>
      <div class="cl-toolbar"><div class="field cl-search"><label for="cl-search">Search records</label><input id="cl-search" type="search" placeholder="Name, session or concern" value="${esc(PC, ui.query)}"></div><div class="field"><label for="cl-filter">Review state</label><select id="cl-filter"><option value="all"${ui.filter === 'all' ? ' selected' : ''}>All records</option><option value="pending"${ui.filter === 'pending' ? ' selected' : ''}>To review</option><option value="information"${ui.filter === 'information' ? ' selected' : ''}>Information requested</option><option value="published"${ui.filter === 'published' ? ' selected' : ''}>Guidance published</option></select></div><div class="field"><label for="cl-sort">Sort by</label><select id="cl-sort"><option value="newest"${ui.sort === 'newest' ? ' selected' : ''}>Newest first</option><option value="oldest"${ui.sort === 'oldest' ? ' selected' : ''}>Oldest first</option><option value="concerns"${ui.sort === 'concerns' ? ' selected' : ''}>Reported concerns</option></select></div></div>
      <div class="table-wrap"><table class="cl-table"><thead><tr><th>Customer</th><th>Capture date</th><th>Customer reported</th><th>Review state</th><th>Follow-up / clinician</th><th><span class="sr-only">Open record</span></th></tr></thead><tbody id="cl-queue-rows">${queueRows(PC)}</tbody></table></div><div id="cl-queue-empty"${filteredQueue(PC).length ? ' class="cl-hidden"' : ''}>${empty(PC, list.length ? 'No matching records' : 'Your review queue is clear', list.length ? 'Try a different search or review-state filter.' : 'A saved session appears here when sharing is enabled and a sample clinician is assigned.', !list.length ? go('/admin/accounts', 'View assignments') : '')}</div><div class="cl-bottomline"><span id="cl-queue-count">${filteredQueue(PC).length} shared records</span><span>No live clinical review time has been established.</span></div></section>`;
  }

  function field(PC, label, key, value, hint, required, type) {
    return `<div class="cl-field"><label for="cl-${key}">${label}${required ? ' <span class="cl-required">*</span>' : ''}</label>${type === 'date' ? `<input id="cl-${key}" name="${key}" type="date" value="${esc(PC, value || '')}"${required ? ' required' : ''}>` : `<textarea id="cl-${key}" name="${key}"${required ? ' required' : ''} placeholder="${esc(PC, hint || '')}">${esc(PC, value || '')}</textarea>`}${hint && type === 'date' ? `<small>${hint}</small>` : ''}</div>`;
  }

  function readout(PC, label, value, source) { return `<div class="cl-readout">${source ? `<span class="cl-source">${source}</span>` : ''}<h4>${label}</h4><p>${esc(PC, value)}</p></div>`; }

  function analysisHTML(PC, s) {
    const analysis = s.analysis;
    if (!analysis || !Array.isArray(analysis.observations) || !analysis.observations.length) return `<span class="cl-source">SYSTEM RESULT</span><div class="notice warning"><strong>Analysis unavailable</strong><p class="small">No completed model output is attached to this session. No image-derived measurements are available for review.</p></div><p class="small muted">You can still review the original evidence. Accepting the report confirms its stated limitations, not a clinical measurement.</p>`;
    const limitations = Array.isArray(analysis.limitations) ? analysis.limitations.join(' ') : analysis.limitations;
    return `<span class="cl-source">RESEARCH OUTPUT</span><div class="notice"><strong>Experimental image segmentation</strong><p class="small">Hair-classified image pixels as a percentage of the complete image. This is not hair density, follicle count, regrowth or a validated scalp measurement.</p></div><div class="table-wrap"><table class="cl-table" style="min-width:0"><thead><tr><th>View</th><th>Hair-classified pixels</th></tr></thead><tbody>${analysis.observations.map(o => `<tr><td>${esc(PC, o.view || 'Unspecified')}</td><td>${typeof o.hairAreaPercent === 'number' && Number.isFinite(o.hairAreaPercent) ? esc(PC, o.hairAreaPercent.toFixed(2)) + '% of image' : 'Unavailable'}</td></tr>`).join('')}</tbody></table></div>${readout(PC, 'Measurement limitations', limitations || 'Image framing, lighting, hair arrangement and model errors affect this output. It must not be used to infer a diagnosis or treatment response.')}${readout(PC, 'Model version', analysis.modelVersion || s.modelVersion || 'Not recorded')}<p class="small muted">These original findings remain unchanged when a demonstration reviewer adds an interpretation or correction.</p>`;
  }

  function valuesFor(s) {
    const source = s.review?.draft || s.guidance || {};
    return {
      decision: s.review?.decision || 'manual', correction: s.review?.correction || '',
      reviewed: source.reviewed || '', assessment: source.assessment || '', limitations: source.limitations || '',
      nextAction: source.nextAction || '', clarification: source.clarification || '', followUp: source.followUp || '', followUpNotes: source.followUpNotes || ''
    };
  }

  function previewHTML(PC, data, s) {
    return `<div class="cl-preview" id="cl-guidance-preview" tabindex="-1"><div class="eyebrow">CUSTOMER PREVIEW</div><h3>Demonstration guidance</h3><p class="muted small">${doctor(PC)} · Sample clinician · ${PC.date(s.date)} session</p>${readout(PC, 'What was reviewed', data.reviewed)}${readout(PC, 'Assessment', data.assessment)}${readout(PC, 'Limitations', data.limitations)}${readout(PC, 'Next action', data.nextAction)}${readout(PC, 'Clarification or further assessment', data.clarification)}${readout(PC, 'Follow-up', `${data.followUp ? PC.date(data.followUp) : 'Not scheduled'}${data.followUpNotes ? '. ' + data.followUpNotes : ''}`)}<p class="cl-inert-note">This will be identified as a demonstration in the customer workspace. It is not advice from a medical professional.</p><button type="button" class="btn primary" id="cl-publish">${s.guidance ? 'Publish revised demo guidance' : 'Publish demo guidance'}</button></div>`;
  }

  function review(PC, id) {
    const s = accessible(PC, id);
    if (!s) return heading('REVIEW WORKSPACE', 'This record is not shared.', 'The review workspace only includes authorised records.') + empty(PC, 'Review access is unavailable', 'Sharing may be off, the record may have been removed, or no sample clinician is assigned.', go('/doctor', 'Back to review queue'));
    const list = shared(PC);
    const refs = list.filter(item => item.id !== s.id);
    const baseline = refs.find(item => item.isBaseline) || refs[refs.length - 1];
    const reference = refs.find(item => item.id === ui.reference) || baseline;
    const views = [...new Set((s.photos || []).map(p => p.view).filter(Boolean))];
    if (!views.length) views.push('Front', 'Top', 'Crown');
    if (!views.includes(ui.view)) ui.view = views[0];
    const v = valuesFor(s);
    const photo = (item, view) => item ? PC.sessionPhoto(item, view) : `<div class="cl-empty"><p>No earlier shared session for this view.</p></div>`;
    const requests = (s.requests || []).filter(r => r.status !== 'resolved');
    return heading('PATIENT RECORD', name(PC), `${PC.date(s.date)} · ${s.isBaseline ? 'Baseline session' : 'Weekly check-in'} · ${s.sample ? 'Demonstration record' : 'Saved upload'}`, go('/doctor', 'Back to queue') + `<button class="btn" id="cl-download">${PC.icon('download', 16)} Download record</button>`) + intro(PC) +
      `<div class="cl-split"><div class="stack">
      ${panel('Original evidence', 'Compare the same view. Source photographs remain unchanged.', `<div class="cl-evidence-tools"><div class="cl-tabs" aria-label="Photo view">${views.map(view => `<button type="button" data-cl-view="${esc(PC, view)}" aria-pressed="${ui.view === view}">${esc(PC, view)}</button>`).join('')}</div><button type="button" class="btn small" id="cl-zoom" aria-pressed="${ui.zoom}">${PC.icon('search', 15)} ${ui.zoom ? 'Reset zoom' : 'Zoom photographs'}</button></div><div class="cl-field"><label for="cl-reference">Comparison session</label><select id="cl-reference"${refs.length ? '' : ' disabled'}>${refs.length ? refs.map(item => `<option value="${esc(PC, item.id)}"${reference?.id === item.id ? ' selected' : ''}>${PC.date(item.date)}${item.isBaseline ? ' · Baseline' : ''}</option>`).join('') : '<option>No earlier shared session</option>'}</select></div><div class="cl-evidence"><div><div class="cl-photo${ui.zoom ? ' cl-zoom' : ''}">${photo(reference, ui.view)}</div><div class="cl-photo-label"><strong>${reference?.isBaseline ? 'Baseline' : 'Comparison'}</strong><span>${reference ? PC.date(reference.date) : 'Not available'}</span></div></div><div><div class="cl-photo${ui.zoom ? ' cl-zoom' : ''}">${photo(s, ui.view)}</div><div class="cl-photo-label"><strong>Selected session</strong><span>${PC.date(s.date)}</span></div></div></div><div class="notice"><strong>Comparison has not been validated.</strong><p class="small">Lighting, positioning and hair arrangement can affect appearance. Original photographs are shown; automated alignment is not available.</p></div><dl class="cl-meta"><div><dt>Image source</dt><dd>${s.sample ? 'Illustrated demonstration' : 'Customer-selected photographs'}</dd></div><div><dt>Model version</dt><dd>${esc(PC, s.analysis?.modelVersion || s.modelVersion || 'No output attached')}</dd></div></dl>`)}
      ${panel('Customer update', 'Reported by the customer, separate from image analysis.', `${readout(PC, 'Routine', text(s.answers?.routine, 'No routine update recorded'), 'CUSTOMER REPORTED')}${readout(PC, 'Difficulty following the routine', text(s.answers?.difficulty, 'Not reported'))}${readout(PC, 'Concern for review', concern(s))}${readout(PC, 'Appearance changes', text(s.answers?.appearance, 'Not reported'))}${readout(PC, 'Additional notes', text(s.notes, 'No additional notes'))}`)}
      ${panel('Shared progress history', `${list.length} authorised sessions in this saved record.`, `<div class="cl-history">${list.map(item => `<a href="#/doctor/review/${encodeURIComponent(item.id)}" data-go="/doctor/review/${esc(PC, item.id)}"${item.id === s.id ? ' aria-current="page"' : ''}><strong>${PC.date(item.date)}</strong><small>${item.isBaseline ? 'Baseline' : esc(PC, item.title || 'Weekly check-in')}</small><small>${esc(PC, item.status)}</small></a>`).join('')}</div>`)}
      ${s.guidance ? panel('Published demonstration', `Version ${s.guidance.version || 1} · ${PC.date(s.guidance.publishedAt)}`, `${readout(PC, 'Assessment', s.guidance.assessment || '')}${readout(PC, 'Next action', s.guidance.nextAction || '')}<p class="small muted">Earlier versions are preserved when this review is amended.</p>`) : ''}
      </div><div class="stack">
      ${panel('Report evaluation', 'The original system result is preserved.', `${analysisHTML(PC, s)}<dl class="cl-meta"><div><dt>Session</dt><dd>${esc(PC, s.id)}</dd></div><div><dt>Current review</dt><dd>${PC.badge(s.status)}</dd></div></dl>`)}
      ${panel(s.guidance ? 'Amend demonstration guidance' : 'Write demonstration guidance', 'Save a draft, then preview the customer’s version.', `<form id="cl-review-form"><div class="cl-field"><label for="cl-decision">Review decision</label><select id="cl-decision" name="decision"><option value="manual"${v.decision === 'manual' ? ' selected' : ''}>Manual evidence review</option><option value="accept"${v.decision === 'accept' ? ' selected' : ''}>Accept findings with their limitations</option><option value="dispute"${v.decision === 'dispute' ? ' selected' : ''}>Dispute a finding or report wording</option><option value="unreliable"${v.decision === 'unreliable' ? ' selected' : ''}>Mark comparison unreliable</option></select><small>Your evaluation is kept separately from the original system result.</small></div>${field(PC, 'Correction or review note', 'correction', v.correction, 'Record a factual correction or explain your decision.', false)}<div class="divider"></div>${field(PC, 'What was reviewed', 'reviewed', v.reviewed, 'Identify the session dates, photo views and customer update.', true)}${field(PC, 'Assessment of the available evidence', 'assessment', v.assessment, 'Describe what the available evidence supports.', true)}${field(PC, 'Important limitations', 'limitations', v.limitations, 'Explain missing information or limits to comparison.', true)}${field(PC, 'Recommended next action', 'nextAction', v.nextAction, 'Give a clear next step for this demonstration.', true)}${field(PC, 'Clarification or further assessment', 'clarification', v.clarification, 'State what else is needed, or state that none is requested.', true)}${field(PC, 'Next review date', 'followUp', v.followUp, 'This sets a date in the follow-up list. No reminder is sent.', true, 'date')}${field(PC, 'Follow-up arrangements', 'followUpNotes', v.followUpNotes, 'Explain how the next review should happen.', true)}<div class="cl-form-actions"><button type="button" class="btn" id="cl-save-draft">Save draft</button><button type="submit" class="btn primary">Preview guidance</button></div><p class="cl-inert-note">Required fields are marked *. Publishing creates a saved demonstration, with the sample clinician’s name and publication time.</p></form><div id="cl-preview-container"></div>`)}
      ${panel('Need more information?', 'A request can be made even when analysis is unavailable.', `<div class="actions"><button class="btn small" id="cl-open-request">${PC.icon('plus', 16)} Request photos or information</button></div>${requests.length ? `<ul class="cl-note-list">${requests.map(r => `<li><strong>${r.type === 'photos' ? 'Photograph requested' : 'Information requested'}</strong>${esc(PC, r.message)}<span class="cl-sub muted small"> ${PC.date(r.date)} · Demonstration</span></li>`).join('')}</ul>` : ''}<div id="cl-request-container">${ui.request ? requestForm() : ''}</div>`)}
      </div></div>`;
  }

  function requestForm() { return `<form class="cl-request" id="cl-request-form"><div class="cl-field"><label for="cl-request-type">Request type</label><select id="cl-request-type" name="type"><option value="photos">Replacement photograph</option><option value="information">Additional information</option></select></div><div class="cl-field"><label for="cl-request-message">What is needed?</label><textarea id="cl-request-message" name="message" required placeholder="Name the view or information needed and explain why."></textarea></div><div class="actions"><button class="btn primary small" type="submit">Save demo request</button><button class="btn small" type="button" id="cl-cancel-request">Cancel</button></div><p class="cl-inert-note">The request appears in your demonstration record. No real clinician receives it.</p></form>`; }

  function followups(PC) {
    let list = shared(PC).filter(s => s.guidance?.followUp);
    const today = PC.today ? PC.today() : new Intl.DateTimeFormat('en-CA', {timeZone: PC.state.profile.timezone || 'Asia/Calcutta', year:'numeric', month:'2-digit', day:'2-digit'}).format(new Date());
    if (ui.followFilter === 'upcoming') list = list.filter(s => s.guidance.followUp >= today);
    if (ui.followFilter === 'past') list = list.filter(s => s.guidance.followUp < today);
    list.sort((a, b) => a.guidance.followUp.localeCompare(b.guidance.followUp));
    return heading('REVIEW WORKSPACE', 'Follow-ups, in one place.', 'Review dates set in published demonstration guidance.', go('/doctor', 'Open review queue')) + intro(PC) + panel('Scheduled reviews', 'Dates are saved in this workspace. Appointment booking and reminders are not connected.', `<div class="cl-tabs" aria-label="Follow-up filter"><button data-cl-follow="all" aria-pressed="${ui.followFilter === 'all'}">All dates</button><button data-cl-follow="upcoming" aria-pressed="${ui.followFilter === 'upcoming'}">Upcoming</button><button data-cl-follow="past" aria-pressed="${ui.followFilter === 'past'}">Past dates</button></div>${list.length ? list.map(s => { const d = new Date(s.guidance.followUp + 'T12:00:00'); return `<article class="cl-follow"><div class="cl-follow-date">${d.toLocaleDateString('en', { month: 'short' })}<b>${d.getDate()}</b>${d.getFullYear()}</div><div><h3>${name(PC)}</h3><span class="tag">Demonstration follow-up</span><p>${esc(PC, s.guidance.followUpNotes || 'Review the next shared check-in.')}</p><p class="small">${doctor(PC)} · Guidance published ${PC.date(s.guidance.publishedAt)}</p></div>${go('/doctor/review/' + encodeURIComponent(s.id), 'Open record', 'small')}</article>`; }).join('') : empty(PC, 'No follow-up dates here yet', ui.followFilter === 'all' ? 'Publish demonstration guidance with a next review date to add a follow-up.' : 'There are no review dates in this view.', go('/doctor', 'Go to review queue'))}`);
  }

  function admin(PC) {
    const list = sessions(PC);
    const waiting = list.filter(s => !s.sample && !s.analysis?.observations?.length).length;
    return heading('OPERATIONS', 'Keep the workflow moving.', 'Manage assignments, review service dependencies and inspect saved activity.') + adminIntro(PC) +
      `<div class="cl-summary"><article><strong>${list.length.toString().padStart(2, '0')}</strong><span>Saved sessions</span></article><article><strong>${PC.state.profile.assigned ? '01' : '00'}</strong><span>Sample clinician assignments</span></article><article><strong>${waiting.toString().padStart(2, '0')}</strong><span>Real uploads without analysis</span></article></div>
      <div class="cl-operational-grid">${panel('Service readiness', 'The website demonstrates the full review workflow.', `<div class="cl-service"><div><h3>Image segmentation</h3><p>Experimental on-device analysis is separate from validated clinical measurements. ${list.filter(s => s.analysis?.observations?.length).length} saved sessions have research output.</p></div><span class="tag">Research only</span></div><div class="cl-service"><div><h3>Accounts and storage</h3><p>Use demonstration records to explore the workflow. Production identity verification and clinical access controls require a reviewed backend.</p></div><span class="tag">Demonstration</span></div><div class="cl-service"><div><h3>Clinical review</h3><p>Recruit and verify a clinical partner before offering professional review.</p></div><span class="tag">Demonstration</span></div>`)}${panel('Access by role', 'Administrative screens show operational metadata.', `<ul class="cl-note-list"><li><strong>Customer</strong>Photographs, check-ins and sharing controls for their own saved record.</li><li><strong>Doctor demonstration</strong>Only shared sessions with an active sample assignment appear in the review queue.</li><li><strong>Administrator demonstration</strong>Assignments, service status and audit events. No clinical photographs appear here.</li><li><strong>Research use</strong>${PC.state.consents.research ? 'The optional research-contact preference is recorded.' : 'Research permission is off.'} No data is sent to a training pipeline.</li></ul>`)}</div>
      <div class="cl-admin-nav"><button data-go="/admin/accounts">${PC.icon('users', 23)}<strong>Accounts & assignments</strong><span>Inspect sample clinician details and manage the demonstration review assignment.</span><span class="cl-link">Manage assignments →</span></button><button data-go="/admin/issues">${PC.icon('alert-circle', 23)}<strong>Processing & delivery</strong><span>See which records are waiting for connected services and a review.</span><span class="cl-link">Inspect service issues →</span></button><button data-go="/admin/audit">${PC.icon('clipboard', 23)}<strong>Access & audit history</strong><span>Trace consent updates, review actions and changes to saved records.</span><span class="cl-link">View activity →</span></button></div>`;
  }

  function accounts(PC) {
    return heading('ADMINISTRATION', 'Accounts & assignments', 'Manage the demonstration assignment without opening clinical photographs.', go('/admin', 'Operations overview')) + adminIntro(PC) +
      `<div class="cl-operational-grid">${panel('Sample clinician', 'An illustrative profile for testing the review workflow.', `<div class="cl-person-row"><div class="cl-person">${PC.icon('user', 22)}</div><div><strong>${doctor(PC)}</strong><div class="muted small">Demonstration profile · Not verified</div></div></div><dl class="cl-meta"><div><dt>Professional registration</dt><dd>Not supplied</dd></div><div><dt>Service availability</dt><dd>No live service</dd></div><div><dt>Verification</dt><dd>Requires a clinical partner</dd></div><div><dt>Demonstration access</dt><dd>${PC.live ? 'Your signed-in account' : 'This browser profile'}</dd></div></dl><div class="divider"></div><p class="small muted">Identity checks, registration verification and multifactor authentication must be implemented before a real clinician can review customers.</p>`)}${panel('Customer assignment', 'Controls access to shared records in this demonstration.', `<div class="cl-person-row"><div class="cl-person">${PC.icon('user', 22)}</div><div><strong>${name(PC)}</strong><div class="muted small">Demonstration customer profile</div></div></div><dl class="cl-meta"><div><dt>Assigned sample clinician</dt><dd>${PC.state.profile.assigned ? doctor(PC) : 'Awaiting assignment'}</dd></div><div><dt>Doctor sharing</dt><dd>${PC.state.consents.sharing ? 'Permission enabled' : 'Permission off'}</dd></div><div><dt>Shared sessions</dt><dd>${sessions(PC).filter(s => s.shared).length}</dd></div><div><dt>Visible in review queue</dt><dd>${shared(PC).length}</dd></div></dl><div class="divider"></div><button class="btn primary" id="cl-assignment">${PC.state.profile.assigned ? 'Remove sample assignment' : 'Assign sample clinician'}</button><p class="cl-inert-note">${PC.state.profile.assigned ? 'Removing the assignment immediately hides this record from the doctor demonstration.' : 'Assignment makes authorised shared sessions visible in the doctor demonstration.'} Sharing permission remains controlled by the customer.</p>`)}</div>`;
  }

  function issues(PC) {
    const list = sessions(PC);
    const missing = list.filter(s => !s.sample && !s.analysis?.observations?.length);
    const notAssigned = !PC.state.profile.assigned ? list.filter(s => s.shared) : [];
    const reviewing = shared(PC).filter(pending);
    return heading('ADMINISTRATION', 'Processing & delivery', 'Failures preserve the original record and keep their next step visible.', go('/admin', 'Operations overview')) + adminIntro(PC) +
      `<div class="cl-operational-grid">${panel('Incomplete analysis', 'Sessions without attached output remain available for manual review.', `<div class="notice warning"><strong>${missing.length} uploaded session${missing.length === 1 ? '' : 's'} without ML analysis</strong><p class="small">The saved record is preserved. Reopen its report to see the model state and any available research-analysis action. No clinical measurement service is connected.</p></div><ul class="cl-note-list"><li><strong>Next step</strong>Check the report for an analysis error. Experimental segmentation does not satisfy clinical validation requirements.</li><li><strong>Preserved records</strong>Original photos, capture dates and customer check-ins remain available in the customer workspace.</li></ul><div class="actions"><button class="btn" id="cl-check-service">Check analysis status</button></div><p class="cl-inert-note">Checking reports stored output availability. It does not run or simulate analysis.</p>`)}${panel('Review operations', 'Queue counts reflect the current sharing permissions.', `<div class="cl-service"><div><h3>Awaiting sample assignment</h3><p>${notAssigned.length} shared session${notAssigned.length === 1 ? '' : 's'} cannot enter the demonstration queue.</p></div>${go('/admin/accounts', 'Assignments', 'small')}</div><div class="cl-service"><div><h3>Open demonstration reviews</h3><p>${reviewing.length} shared session${reviewing.length === 1 ? '' : 's'} without published guidance.</p></div>${go('/doctor', 'Review queue', 'small')}</div><div class="cl-service"><div><h3>Notifications</h3><p>No email, text or push provider is connected. No external notifications have been delivered.</p></div></div><div class="cl-service"><div><h3>Overdue reviews</h3><p>No service hours or completion targets have been established. Reviews are not labelled overdue.</p></div></div>`)}</div>
      <section class="panel" style="margin-top:24px"><div class="panel-head"><div><h2>Saved record status</h2><p class="muted small">Operational metadata only. No photographs are included.</p></div></div>${list.length ? `<div class="table-wrap"><table class="cl-table"><thead><tr><th>Session</th><th>Capture date</th><th>Current state</th><th>Sharing</th><th>Next step</th></tr></thead><tbody>${list.map(s => `<tr><td><span class="cl-title">${esc(PC, s.id)}</span>${s.sample ? '<span class="cl-sub">Demonstration record</span>' : '<span class="cl-sub">Saved upload</span>'}</td><td>${PC.date(s.date)}</td><td>${PC.badge(s.status)}</td><td>${s.shared && PC.state.consents.sharing ? 'Sharing enabled' : 'Not shared'}</td><td>${!s.sample && !s.analysis?.observations?.length ? 'Inspect analysis state in the customer report' : !PC.state.profile.assigned && s.shared ? 'Assign a sample clinician' : s.guidance ? 'See follow-up date in review workspace' : 'Complete demonstration review'}</td></tr>`).join('')}</tbody></table></div>` : empty(PC, 'No saved sessions', 'New records will appear here after a customer check-in.')}</section>`;
  }

  function auditPage(PC) {
    const events = [...(PC.state.audit || [])].reverse();
    return heading('ADMINISTRATION', 'Access & audit history', 'Inspect the sequence of changes saved in your workspace.', go('/admin', 'Operations overview') + '<button class="btn" id="cl-export-audit">Export activity</button>') + adminIntro(PC) +
      `<div class="cl-operational-grid">${panel('Current permissions', 'Permissions are separate and remain under customer control.', `<ul class="cl-note-list">${[['Photo and check-in storage', 'storage'], ['AI analysis', 'analysis'], ['Sharing with assigned clinician', 'sharing'], ['Optional reminders', 'reminders'], ['Optional research use', 'research']].map(([label, key]) => `<li><strong>${label}</strong>${PC.state.consents[key] ? 'Permission enabled' : 'Permission not enabled'}</li>`).join('')}</ul><p class="cl-inert-note">Clinical role separation is demonstrated within your own account. This activity history is not a tamper-resistant clinical audit system.</p>`)}${panel('Activity record', `${events.length} saved event${events.length === 1 ? '' : 's'}.`, events.length ? events.map(event => `<div class="cl-audit-event"><time datetime="${esc(PC, event.date)}">${PC.date(event.date)}<br>${new Date(event.date).toLocaleTimeString('en', { hour: '2-digit', minute: '2-digit' })}</time><span>${esc(PC, event.event || event.action || 'Saved record updated')}</span></div>`).join('') : empty(PC, 'No activity recorded yet', 'Saved changes to consent, assignments and reviews will appear here.'))}</div>`;
  }

  function readForm() {
    const form = document.getElementById('cl-review-form');
    return form ? Object.fromEntries(new FormData(form).entries()) : null;
  }

  async function storeDraft(PC, s, data, message, render) {
    const previousReview = s.review;
    const previousAudit = [...(PC.state.audit || [])];
    s.review = { ...(s.review || {}), decision: data.decision, correction: data.correction, draft: { reviewed: data.reviewed, assessment: data.assessment, limitations: data.limitations, nextAction: data.nextAction, clarification: data.clarification, followUp: data.followUp, followUpNotes: data.followUpNotes }, savedAt: new Date().toISOString() };
    audit(PC, 'Demonstration review draft saved for session ' + s.id);
    if (!await save(PC)) { s.review = previousReview; PC.state.audit = previousAudit; return false; }
    if (render) PC.render();
    if (message) PC.toast(message);
    return true;
  }

  function bindReview(PC, id) {
    const s = accessible(PC, id);
    if (!s) return;
    const on = (key, event, action) => { const el = document.getElementById(key); if (el) el.addEventListener(event, action); };
    const preserve = async () => { const data = readForm(); return data ? await storeDraft(PC, s, data, null, false) : true; };
    document.querySelectorAll('[data-cl-view]').forEach(button => button.addEventListener('click', async () => { if (!await preserve()) return; ui.view = button.dataset.clView; PC.render(); }));
    on('cl-reference', 'change', async e => { const reference = e.target.value; if (!await preserve()) return; ui.reference = reference; PC.render(); });
    on('cl-zoom', 'click', () => { ui.zoom = !ui.zoom; document.querySelectorAll('.cl-photo').forEach(el => el.classList.toggle('cl-zoom', ui.zoom)); const button = document.getElementById('cl-zoom'); button.setAttribute('aria-pressed', String(ui.zoom)); button.innerHTML = PC.icon('search', 15) + (ui.zoom ? ' Reset zoom' : ' Zoom photographs'); });
    on('cl-download', 'click', () => PC.downloadReport(s.id));
    on('cl-save-draft', 'click', async () => { await storeDraft(PC, s, readForm(), 'Demonstration review draft saved.', false); });
    on('cl-review-form', 'input', () => { const preview = document.getElementById('cl-preview-container'); if (preview?.innerHTML) preview.innerHTML = '<p class="small muted">The draft changed. Preview again before publishing.</p>'; });
    on('cl-review-form', 'submit', async e => {
      e.preventDefault();
      const form = e.currentTarget;
      if (!form.reportValidity()) return;
      const data = readForm();
      const required = ['reviewed', 'assessment', 'limitations', 'nextAction', 'clarification', 'followUp', 'followUpNotes'];
      if (required.some(key => !data[key]?.trim())) { PC.toast('Complete every required field before previewing.'); return; }
      if ((data.decision === 'dispute' || data.decision === 'unreliable') && !data.correction.trim()) { document.getElementById('cl-correction').focus(); PC.toast('Explain the disputed wording or unreliable comparison in the review note.'); return; }
      if (!await storeDraft(PC, s, data, null, false)) return;
      document.getElementById('cl-preview-container').innerHTML = previewHTML(PC, data, s);
      document.getElementById('cl-guidance-preview').focus();
      document.getElementById('cl-publish').addEventListener('click', async e => {
        if (!accessible(PC, id)) { PC.toast('Sharing or assignment changed. Reopen the review queue.'); PC.render(); return; }
        const publishButton = e.currentTarget;
        publishButton.disabled = true;
        const previous = { guidance:s.guidance, guidanceHistory:[...(s.guidanceHistory || [])], draft:s.review.draft, status:s.status, notifications:[...(PC.state.notifications || [])], audit:[...(PC.state.audit || [])] };
        if (s.guidance) (s.guidanceHistory || (s.guidanceHistory = [])).push({ ...s.guidance });
        s.guidance = { reviewed: data.reviewed.trim(), assessment: data.assessment.trim(), limitations: data.limitations.trim(), nextAction: data.nextAction.trim(), clarification: data.clarification.trim(), followUp: data.followUp, followUpNotes: data.followUpNotes.trim(), publishedAt: new Date().toISOString(), version: (s.guidance?.version || 0) + 1, author: PC.state.profile.doctor || 'Dr. Morgan Lee', demo: true };
        s.status = 'Guidance published'; s.guidanceNeedsReview = false; s.guidanceNeedsReview = false;
        s.review.draft = null;
        (PC.state.notifications || (PC.state.notifications = [])).unshift({ id: 'guidance-' + Date.now(), title: 'Demonstration guidance is ready', message: 'A sample review has been saved for your ' + PC.date(s.date) + ' session.', date: new Date().toISOString(), read: false, route: '/guidance/' + s.id, type: 'guidance', sessionId: s.id });
        if (!await commit(PC, 'Demonstration guidance version ' + s.guidance.version + ' published for session ' + s.id, 'Demo guidance published in the customer record.')) {
          s.guidance = previous.guidance; s.guidanceHistory = previous.guidanceHistory; s.review.draft = previous.draft; s.status = previous.status; PC.state.notifications = previous.notifications; PC.state.audit = previous.audit; publishButton.disabled = false;
        }
      });
    });
    const wireRequest = () => {
      const cancel = document.getElementById('cl-cancel-request');
      if (cancel) cancel.addEventListener('click', () => { ui.request = false; document.getElementById('cl-request-container').innerHTML = ''; });
      const form = document.getElementById('cl-request-form');
      if (form) form.addEventListener('submit', async e => {
        e.preventDefault();
        const data = Object.fromEntries(new FormData(form).entries());
        if (!data.message?.trim()) return;
        if (!await preserve()) return;
        const previous = { requests:[...(s.requests || [])], request:s.request, status:s.status, notifications:[...(PC.state.notifications || [])], audit:[...(PC.state.audit || [])] };
        const request = { id: 'request-' + Date.now(), type: data.type, message: data.message.trim(), date: new Date().toISOString(), status: 'open', demo: true };
        (s.requests || (s.requests = [])).push(request);
        s.status = data.type === 'photos' ? 'Retake required' : 'More information needed';
        s.request = request;
        ui.request = false;
        (PC.state.notifications || (PC.state.notifications = [])).unshift({ id: request.id, title: data.type === 'photos' ? 'Demonstration photo request' : 'Demonstration information request', message: request.message, date: request.date, read: false, route: '/guidance/' + s.id, type: 'request', sessionId: s.id });
        if (!await commit(PC, 'Demonstration ' + data.type + ' request saved for session ' + s.id, 'Demo request saved in the customer record.')) { s.requests = previous.requests; s.request = previous.request; s.status = previous.status; PC.state.notifications = previous.notifications; PC.state.audit = previous.audit; ui.request = true; }
      });
    };
    on('cl-open-request', 'click', () => { ui.request = true; document.getElementById('cl-request-container').innerHTML = requestForm(); wireRequest(); document.getElementById('cl-request-message').focus(); });
    wireRequest();
  }

  window.Clinical = {
    render(route, PC) {
      let html = null;
      if (route === '/doctor') html = queue(PC);
      else if (route.startsWith('/doctor/review/')) html = review(PC, decodeURIComponent(route.split('/')[3] || ''));
      else if (route === '/follow-ups') html = followups(PC);
      else if (route === '/admin') html = admin(PC);
      else if (route === '/admin/accounts') html = accounts(PC);
      else if (route === '/admin/issues') html = issues(PC);
      else if (route === '/admin/audit') html = auditPage(PC);
      return html == null ? null : style + html;
    },
    bind(route, PC) {
      if (route === '/doctor') {
        const refresh = () => { document.getElementById('cl-queue-rows').innerHTML = queueRows(PC); const count = filteredQueue(PC).length; document.getElementById('cl-queue-count').textContent = count + ' shared records'; document.getElementById('cl-queue-empty').classList.toggle('cl-hidden', !!count); };
        document.getElementById('cl-search')?.addEventListener('input', e => { ui.query = e.target.value; refresh(); });
        document.getElementById('cl-filter')?.addEventListener('change', e => { ui.filter = e.target.value; refresh(); });
        document.getElementById('cl-sort')?.addEventListener('change', e => { ui.sort = e.target.value; refresh(); });
      }
      if (route.startsWith('/doctor/review/')) bindReview(PC, decodeURIComponent(route.split('/')[3] || ''));
      if (route === '/follow-ups') document.querySelectorAll('[data-cl-follow]').forEach(button => button.addEventListener('click', () => { ui.followFilter = button.dataset.clFollow; PC.render(); }));
      if (route === '/admin/accounts') document.getElementById('cl-assignment')?.addEventListener('click', async () => { const previous = PC.state.profile.assigned; const previousAudit = [...(PC.state.audit || [])]; PC.state.profile.assigned = !previous; if (!await commit(PC, PC.state.profile.assigned ? 'Sample clinician assignment enabled' : 'Sample clinician assignment removed', PC.state.profile.assigned ? 'Sample clinician assigned to authorised records.' : 'Sample assignment removed. Records are hidden from the review queue.')) { PC.state.profile.assigned = previous; PC.state.audit = previousAudit; PC.render(); } });
      if (route === '/admin/issues') document.getElementById('cl-check-service')?.addEventListener('click', async () => { const available = sessions(PC).filter(s => s.analysis?.observations?.length).length; audit(PC, 'Stored research analysis checked: ' + available + ' sessions with model output'); if (await save(PC)) PC.toast(available + ' saved sessions have experimental image-segmentation output. Clinical measurements remain unavailable.'); });
      if (route === '/admin/audit') document.getElementById('cl-export-audit')?.addEventListener('click', () => {
        const contents = JSON.stringify({ product: 'ProgressCheck', environment: PC.live ? 'Account demonstration' : 'Browser demonstration', exportedAt: new Date().toISOString(), permissions: PC.state.consents, events: PC.state.audit || [] }, null, 2);
        const url = URL.createObjectURL(new Blob([contents], { type: 'application/json' }));
        const a = document.createElement('a'); a.href = url; a.download = 'progresscheck-activity.json'; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); PC.toast('Saved activity exported.');
      });
    }
  };
})();
